# Raw vector layers from /data/gold/atlas_4326/
# Generated for TSIRD mapserver - canonical EPSG:4326 shapefile atlas
#
# CHANGELOG 2026-02-21:
# - Fixed all OGR DATA field names (now correctly reference actual shapefile layer names)
# - Removed all PROJECTION blocks (data is canonically EPSG:4326, MAP-level projection handles reprojection)
# - Verified all CONNECTION paths map to existing files in /data/gold/atlas_4326/
#
# GetFeatureInfo Metadata Strategy:
# - GetFeatureInfo is enabled via METADATA keywords: wms_include_items, gml_include_items, wms_feature_info_mime_type
# - Each layer includes TEMPLATE "dummy.html" for HTML output format
# - The DUMP keyword (unsupported in MapServer 8.6.0) has been removed; METADATA + TEMPLATE provide feature attributes
# - Each layer includes curated field lists for meaningful attribute queries
# - See docs/atlas/vector_featureinfo_plan.yml for field curation rationale
#
# Projection Handling:
# - All data is EPSG:4326 (WGS 84 geographic)
# - MAP-level PROJECTION is EPSG:4326, no layer-level projection blocks needed
# - OGR layers do not have PROJECTION declarations (relies on MAP-level projection)
# - MapServer automatically handles CRS conversion from EPSG:4326 as needed

LAYER
  NAME "ethiopia_zones"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE OGR
  CONNECTION "/data/gold/atlas_4326/bound03.shp"
  DATA "bound03"
  LABELITEM "ZONES"
  LABELMAXSCALEDENOM 3000000
  METADATA
    "wms_title" "Ethiopia - Zones (pre-91)"
    "wms_srs" "EPSG:3857 EPSG:4326"
    "wms_enable_request" "*"
    "wms_queryable" "true"
    "wms_feature_info_mime_type" "text/plain"
    "gml_include_items" "ZONES,AREA,PERIMETER,ETZONES01C,ETZONES01C_1"
    "wms_include_items" "ZONES,AREA,PERIMETER,ETZONES01C,ETZONES01C_1"
  END
  TEMPLATE "dummy.html"
  CLASS
    NAME "Zones"
    STYLE
      COLOR 171 170 107
      OUTLINECOLOR 0 0 0
      OPACITY 50
    END
    LABEL
      COLOR 50 50 50
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 9
      POSITION AUTO
      PARTIALS FALSE
    END
  END
END

# Development-only CHIRPS v3 seasonal rainfall-condition summary. This layer
# deliberately renders only rows that passed the grid-coverage quality gate.
LAYER
  NAME "tigray_drought_chirps_dev"
  TYPE POLYGON
  STATUS OFF
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=tsird-postgis port=5432 dbname=tsird user=tsird password=change_me_strong"
  DATA "geometry FROM (SELECT t.gid, t.geometry, t.\"TABIA\", t.\"WEREDA\", c.percentile, c.condition_class, c.rainfall_mm, c.baseline_median_mm, c.grid_cell_count, c.coverage_pct, c.quality_status FROM tigray_tabias_ws t JOIN tsird.drought_tabia_rainfall_condition c USING (tsird_tabia_id) WHERE c.run_id=(SELECT run_id FROM tsird.drought_rainfall_run WHERE status='development' ORDER BY source_latest_month DESC, cardinality(season_months) DESC, created_at DESC LIMIT 1) AND c.quality_status='ok') AS drought USING UNIQUE gid USING SRID=4326"
  CLASSITEM "rainfall_mm"
  METADATA
    "wms_title" "Tigray Latest Rainfall Condition (CHIRPS v3, development)"
    "wms_srs" "EPSG:3857"
    "wms_enable_request" "*"
    "wms_queryable" "true"
    "wms_feature_info_mime_type" "text/plain"
    "gml_include_items" "TABIA,WEREDA,percentile,condition_class,rainfall_mm,baseline_median_mm,grid_cell_count,coverage_pct,quality_status"
    "wms_include_items" "TABIA,WEREDA,percentile,condition_class,rainfall_mm,baseline_median_mm,grid_cell_count,coverage_pct,quality_status"
  END
  TEMPLATE "dummy.html"
  CLASS NAME "Below 50 mm" EXPRESSION ([rainfall_mm] < 50) STYLE COLOR 255 247 188 OUTLINECOLOR 205 185 100 WIDTH 0.4 END END
  CLASS NAME "50–100 mm" EXPRESSION (([rainfall_mm] >= 50) AND ([rainfall_mm] < 100)) STYLE COLOR 254 227 145 OUTLINECOLOR 205 170 75 WIDTH 0.4 END END
  CLASS NAME "100–150 mm" EXPRESSION (([rainfall_mm] >= 100) AND ([rainfall_mm] < 150)) STYLE COLOR 254 196 79 OUTLINECOLOR 190 140 50 WIDTH 0.4 END END
  CLASS NAME "150–200 mm" EXPRESSION (([rainfall_mm] >= 150) AND ([rainfall_mm] < 200)) STYLE COLOR 254 153 41 OUTLINECOLOR 180 105 45 WIDTH 0.4 END END
  CLASS NAME "200–250 mm" EXPRESSION (([rainfall_mm] >= 200) AND ([rainfall_mm] < 250)) STYLE COLOR 236 112 20 OUTLINECOLOR 165 80 35 WIDTH 0.4 END END
  CLASS NAME "250–300 mm" EXPRESSION (([rainfall_mm] >= 250) AND ([rainfall_mm] < 300)) STYLE COLOR 204 76 2 OUTLINECOLOR 135 60 20 WIDTH 0.4 END END
  CLASS NAME "300–350 mm" EXPRESSION (([rainfall_mm] >= 300) AND ([rainfall_mm] < 350)) STYLE COLOR 153 52 4 OUTLINECOLOR 110 45 20 WIDTH 0.4 END END
  CLASS NAME "350–400 mm" EXPRESSION (([rainfall_mm] >= 350) AND ([rainfall_mm] < 400)) STYLE COLOR 102 37 6 OUTLINECOLOR 80 35 20 WIDTH 0.4 END END
  CLASS NAME "400–450 mm" EXPRESSION (([rainfall_mm] >= 400) AND ([rainfall_mm] < 450)) STYLE COLOR 71 25 8 OUTLINECOLOR 60 25 18 WIDTH 0.4 END END
  CLASS NAME "At least 450 mm" EXPRESSION ([rainfall_mm] >= 450) STYLE COLOR 45 18 8 OUTLINECOLOR 45 18 15 WIDTH 0.4 END END
END

# Development evidence layers.  These use the latest local run only and keep
# source-specific value bands: they are not risk, drought, or food-security classes.
LAYER
  NAME "tigray_drought_ndvi_dev"
  TYPE POLYGON
  STATUS OFF
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=tsird-postgis port=5432 dbname=tsird user=tsird password=change_me_strong"
  DATA "geometry FROM (SELECT t.gid,t.geometry,t.\"TABIA\",t.\"WEREDA\",n.ndvi_mean,n.coverage_pct,n.quality_status FROM tigray_tabias_ws t JOIN tsird.drought_tabia_ndvi n USING (tsird_tabia_id) WHERE n.run_id=(SELECT run_id FROM tsird.drought_ndvi_run ORDER BY observation_end DESC, created_at DESC LIMIT 1) AND n.quality_status='ok') AS ndvi USING UNIQUE gid USING SRID=4326"
  CLASSITEM "ndvi_mean"
  METADATA
    "wms_title" "Tigray Vegetation Condition (NDVI, development)"
    "wms_srs" "EPSG:3857" "wms_enable_request" "*" "wms_queryable" "true"
    "gml_include_items" "TABIA,WEREDA,ndvi_mean,coverage_pct,quality_status"
  END
  TEMPLATE "dummy.html"
  CLASS NAME "NDVI below 0.10" EXPRESSION ([ndvi_mean] < 0.10) STYLE COLOR 165 0 38 OUTLINECOLOR 110 40 55 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.10–0.20" EXPRESSION (([ndvi_mean] >= 0.10) AND ([ndvi_mean] < 0.20)) STYLE COLOR 215 48 39 OUTLINECOLOR 150 50 55 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.20–0.30" EXPRESSION (([ndvi_mean] >= 0.20) AND ([ndvi_mean] < 0.30)) STYLE COLOR 244 109 67 OUTLINECOLOR 175 70 50 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.30–0.40" EXPRESSION (([ndvi_mean] >= 0.30) AND ([ndvi_mean] < 0.40)) STYLE COLOR 253 174 97 OUTLINECOLOR 180 110 60 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.40–0.50" EXPRESSION (([ndvi_mean] >= 0.40) AND ([ndvi_mean] < 0.50)) STYLE COLOR 254 224 139 OUTLINECOLOR 180 150 75 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.50–0.60" EXPRESSION (([ndvi_mean] >= 0.50) AND ([ndvi_mean] < 0.60)) STYLE COLOR 217 239 139 OUTLINECOLOR 145 165 75 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.60–0.70" EXPRESSION (([ndvi_mean] >= 0.60) AND ([ndvi_mean] < 0.70)) STYLE COLOR 166 217 106 OUTLINECOLOR 100 145 65 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.70–0.80" EXPRESSION (([ndvi_mean] >= 0.70) AND ([ndvi_mean] < 0.80)) STYLE COLOR 102 189 99 OUTLINECOLOR 65 125 65 WIDTH 0.4 END END
  CLASS NAME "NDVI 0.80–0.90" EXPRESSION (([ndvi_mean] >= 0.80) AND ([ndvi_mean] < 0.90)) STYLE COLOR 26 152 80 OUTLINECOLOR 35 105 55 WIDTH 0.4 END END
  CLASS NAME "NDVI at least 0.90" EXPRESSION ([ndvi_mean] >= 0.90) STYLE COLOR 0 104 55 OUTLINECOLOR 15 75 40 WIDTH 0.4 END END
END

