# FAO WaPOR water-use context. Transpiration is vegetation water use in the
# provider's dekadal composite, expressed as a daily mean (mm/day), while AETI
# remains a supporting GetFeatureInfo field. These numeric bands do not express
# crop yield, drought, or priority.
LAYER
  NAME "tigray_drought_wapor_dev"
  TYPE POLYGON
  STATUS OFF
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=tsird-postgis port=5432 dbname=tsird user=tsird password=change_me_strong"
  DATA "geometry FROM (SELECT t.gid,t.geometry,t.\"TABIA\",t.\"WEREDA\",w.transpiration_mm,w.aeti_mm,w.coverage_pct,w.quality_status FROM tigray_tabias_ws t JOIN tsird.drought_tabia_wapor w USING (tsird_tabia_id) WHERE w.run_id=(SELECT run_id FROM tsird.drought_wapor_run ORDER BY source_period_end DESC, created_at DESC LIMIT 1) AND w.quality_status='ok') AS wapor USING UNIQUE gid USING SRID=4326"
  CLASSITEM "transpiration_mm"
  METADATA
    "wms_title" "Tigray Agricultural Water Use (FAO WaPOR transpiration, development)"
    "wms_srs" "EPSG:3857" "wms_enable_request" "*" "wms_queryable" "true"
    "gml_include_items" "TABIA,WEREDA,transpiration_mm,aeti_mm,coverage_pct,quality_status"
  END
  TEMPLATE "dummy.html"
  CLASS NAME "Transpiration below 0.5 mm/day" EXPRESSION ([transpiration_mm] < 0.5) STYLE COLOR 255 247 188 OUTLINECOLOR 205 185 100 WIDTH 0.4 END END
  CLASS NAME "0.5–1.0 mm/day" EXPRESSION (([transpiration_mm] >= 0.5) AND ([transpiration_mm] < 1.0)) STYLE COLOR 254 227 145 OUTLINECOLOR 205 170 75 WIDTH 0.4 END END
  CLASS NAME "1.0–1.5 mm/day" EXPRESSION (([transpiration_mm] >= 1.0) AND ([transpiration_mm] < 1.5)) STYLE COLOR 254 196 79 OUTLINECOLOR 190 140 50 WIDTH 0.4 END END
  CLASS NAME "1.5–2.0 mm/day" EXPRESSION (([transpiration_mm] >= 1.5) AND ([transpiration_mm] < 2.0)) STYLE COLOR 254 153 41 OUTLINECOLOR 180 105 45 WIDTH 0.4 END END
  CLASS NAME "2.0–2.5 mm/day" EXPRESSION (([transpiration_mm] >= 2.0) AND ([transpiration_mm] < 2.5)) STYLE COLOR 236 112 20 OUTLINECOLOR 165 80 35 WIDTH 0.4 END END
  CLASS NAME "2.5–3.0 mm/day" EXPRESSION (([transpiration_mm] >= 2.5) AND ([transpiration_mm] < 3.0)) STYLE COLOR 204 76 2 OUTLINECOLOR 135 60 20 WIDTH 0.4 END END
  CLASS NAME "3.0–3.5 mm/day" EXPRESSION (([transpiration_mm] >= 3.0) AND ([transpiration_mm] < 3.5)) STYLE COLOR 153 52 4 OUTLINECOLOR 110 45 20 WIDTH 0.4 END END
  CLASS NAME "3.5–4.0 mm/day" EXPRESSION (([transpiration_mm] >= 3.5) AND ([transpiration_mm] < 4.0)) STYLE COLOR 102 37 6 OUTLINECOLOR 80 35 20 WIDTH 0.4 END END
  CLASS NAME "4.0–5.0 mm/day" EXPRESSION (([transpiration_mm] >= 4.0) AND ([transpiration_mm] < 5.0)) STYLE COLOR 71 25 8 OUTLINECOLOR 60 25 18 WIDTH 0.4 END END
  CLASS NAME "At least 5.0 mm/day" EXPRESSION ([transpiration_mm] >= 5.0) STYLE COLOR 45 18 8 OUTLINECOLOR 45 18 15 WIDTH 0.4 END END
END

LAYER
  NAME "tigray_drought_wapor_raw_dev"
  TYPE RASTER
  STATUS OFF
  DATA "/data/drought/published/wapor-transpiration-current.tif"
  METADATA
    "wms_title" "Tigray Agricultural Water Use (FAO WaPOR transpiration native grid, development)"
    "wms_srs" "EPSG:3857 EPSG:4326" "wms_enable_request" "*"
  END
  CLASS NAME "Transpiration below 0.5 mm/day" EXPRESSION ([pixel] < 0.5) STYLE COLOR 255 247 188 END END
  CLASS NAME "0.5–1.0 mm/day" EXPRESSION (([pixel] >= 0.5) AND ([pixel] < 1.0)) STYLE COLOR 254 227 145 END END
  CLASS NAME "1.0–1.5 mm/day" EXPRESSION (([pixel] >= 1.0) AND ([pixel] < 1.5)) STYLE COLOR 254 196 79 END END
  CLASS NAME "1.5–2.0 mm/day" EXPRESSION (([pixel] >= 1.5) AND ([pixel] < 2.0)) STYLE COLOR 254 153 41 END END
  CLASS NAME "2.0–2.5 mm/day" EXPRESSION (([pixel] >= 2.0) AND ([pixel] < 2.5)) STYLE COLOR 236 112 20 END END
  CLASS NAME "2.5–3.0 mm/day" EXPRESSION (([pixel] >= 2.5) AND ([pixel] < 3.0)) STYLE COLOR 204 76 2 END END
  CLASS NAME "3.0–3.5 mm/day" EXPRESSION (([pixel] >= 3.0) AND ([pixel] < 3.5)) STYLE COLOR 153 52 4 END END
  CLASS NAME "3.5–4.0 mm/day" EXPRESSION (([pixel] >= 3.5) AND ([pixel] < 4.0)) STYLE COLOR 102 37 6 END END
  CLASS NAME "4.0–5.0 mm/day" EXPRESSION (([pixel] >= 4.0) AND ([pixel] < 5.0)) STYLE COLOR 71 25 8 END END
  CLASS NAME "At least 5.0 mm/day" EXPRESSION ([pixel] >= 5.0) STYLE COLOR 45 18 8 END END
END

LAYER
  NAME "tigray_drought_road_accessibility_dev"
  TYPE POLYGON
  STATUS OFF
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=tsird-postgis port=5432 dbname=tsird user=tsird password=change_me_strong"
  DATA "geometry FROM (SELECT t.gid,t.geometry,t.\"TABIA\",t.\"WEREDA\",a.nearest_road_m,a.tigray_roads_2006_intersects,a.quality_status FROM tigray_tabias_ws t JOIN tsird.drought_tabia_road_accessibility a USING (tsird_tabia_id) WHERE a.run_id=(SELECT run_id FROM tsird.drought_road_accessibility_run WHERE status='development' ORDER BY created_at DESC LIMIT 1) AND a.quality_status='ok') AS road_access USING UNIQUE gid USING SRID=4326"
  CLASSITEM "nearest_road_m"
  METADATA
    "wms_title" "Federal and Regional Road Network Proximity (ERA + TRRA, development)"
    "wms_srs" "EPSG:3857" "wms_enable_request" "*" "wms_queryable" "true"
    "gml_include_items" "TABIA,WEREDA,nearest_road_m,tigray_roads_2006_intersects,quality_status"
  END
  TEMPLATE "dummy.html"
  CLASS NAME "Within 0.9 km" EXPRESSION ([nearest_road_m] < 900) STYLE COLOR 26 152 80 OUTLINECOLOR 30 100 60 WIDTH 0.4 END END
  CLASS NAME "0.9–2.7 km" EXPRESSION (([nearest_road_m] >= 900) AND ([nearest_road_m] < 2700)) STYLE COLOR 166 217 106 OUTLINECOLOR 90 140 70 WIDTH 0.4 END END
  CLASS NAME "2.7–5.5 km" EXPRESSION (([nearest_road_m] >= 2700) AND ([nearest_road_m] < 5500)) STYLE COLOR 254 224 139 OUTLINECOLOR 160 130 70 WIDTH 0.4 END END
  CLASS NAME "5.5–10 km" EXPRESSION (([nearest_road_m] >= 5500) AND ([nearest_road_m] < 10000)) STYLE COLOR 252 141 89 OUTLINECOLOR 160 100 70 WIDTH 0.4 END END
  CLASS NAME "10 km or farther" EXPRESSION ([nearest_road_m] >= 10000) STYLE COLOR 215 48 39 OUTLINECOLOR 110 70 70 WIDTH 0.4 END END
END

LAYER
  NAME "tigray_drought_population_dev"
  TYPE POLYGON
  STATUS OFF
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=tsird-postgis port=5432 dbname=tsird user=tsird password=change_me_strong"
  DATA "geometry FROM (SELECT t.gid,t.geometry,t.\"TABIA\",t.\"WEREDA\",p.population_total,p.people_per_sq_km,p.coverage_pct,p.quality_status FROM tigray_tabias_ws t JOIN tsird.drought_tabia_population p USING (tsird_tabia_id) WHERE p.run_id=(SELECT run_id FROM tsird.drought_population_run WHERE status='development' ORDER BY created_at DESC LIMIT 1) AND p.quality_status='ok') AS population USING UNIQUE gid USING SRID=4326"
  CLASSITEM "population_total"
  METADATA
    "wms_title" "WorldPop Population Baseline (2025, Tabia, development)"
