  CLASS NAME "4,015–5,257 people" EXPRESSION (([population_total] >= 4015) AND ([population_total] < 5257)) STYLE COLOR 222 235 247 OUTLINECOLOR 160 180 200 WIDTH 0.4 END END
  CLASS NAME "5,257–6,093 people" EXPRESSION (([population_total] >= 5257) AND ([population_total] < 6093)) STYLE COLOR 198 219 239 OUTLINECOLOR 140 165 190 WIDTH 0.4 END END
  CLASS NAME "6,093–6,964 people" EXPRESSION (([population_total] >= 6093) AND ([population_total] < 6964)) STYLE COLOR 158 202 225 OUTLINECOLOR 110 145 180 WIDTH 0.4 END END
  CLASS NAME "6,964–7,955 people" EXPRESSION (([population_total] >= 6964) AND ([population_total] < 7955)) STYLE COLOR 107 174 214 OUTLINECOLOR 80 125 165 WIDTH 0.4 END END
  CLASS NAME "7,955–9,114 people" EXPRESSION (([population_total] >= 7955) AND ([population_total] < 9114)) STYLE COLOR 66 146 198 OUTLINECOLOR 55 105 150 WIDTH 0.4 END END
  CLASS NAME "9,114–10,753 people" EXPRESSION (([population_total] >= 9114) AND ([population_total] < 10753)) STYLE COLOR 33 113 181 OUTLINECOLOR 40 85 135 WIDTH 0.4 END END
  CLASS NAME "10,753–13,253 people" EXPRESSION (([population_total] >= 10753) AND ([population_total] < 13253)) STYLE COLOR 8 81 156 OUTLINECOLOR 25 60 115 WIDTH 0.4 END END
  CLASS NAME "13,253–18,451 people" EXPRESSION (([population_total] >= 13253) AND ([population_total] < 18451)) STYLE COLOR 8 48 107 OUTLINECOLOR 20 40 85 WIDTH 0.4 END END
  CLASS NAME "18,451 people or more" EXPRESSION ([population_total] >= 18451) STYLE COLOR 4 31 74 OUTLINECOLOR 15 30 60 WIDTH 0.4 END END
END

LAYER
  NAME "tigray_drought_cropland_dev"
  TYPE POLYGON
  STATUS OFF
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=tsird-postgis port=5432 dbname=tsird user=tsird password=change_me_strong"
  DATA "geometry FROM (SELECT t.gid,t.geometry,t.\"TABIA\",t.\"WEREDA\",c.cropland_pct,c.cropland_area_ha,c.coverage_pct,c.quality_status FROM tigray_tabias_ws t JOIN tsird.drought_tabia_cropland c USING (tsird_tabia_id) WHERE c.run_id=(SELECT run_id FROM tsird.drought_cropland_run WHERE status='development' ORDER BY created_at DESC LIMIT 1) AND c.quality_status='ok') AS cropland USING UNIQUE gid USING SRID=4326"
  CLASSITEM "cropland_pct"
  METADATA
    "wms_title" "ESA WorldCover Cropland Share (2021, Tabia, development)"
    "wms_srs" "EPSG:3857" "wms_enable_request" "*" "wms_queryable" "true"
    "gml_include_items" "TABIA,WEREDA,cropland_pct,cropland_area_ha,coverage_pct,quality_status"
  END
  TEMPLATE "dummy.html"
  CLASS NAME "Below 7.9% cropland" EXPRESSION ([cropland_pct] < 7.9) STYLE COLOR 255 255 229 OUTLINECOLOR 215 205 140 WIDTH 0.4 END END
  CLASS NAME "7.9–15.5% cropland" EXPRESSION (([cropland_pct] >= 7.9) AND ([cropland_pct] < 15.5)) STYLE COLOR 255 247 188 OUTLINECOLOR 210 190 110 WIDTH 0.4 END END
  CLASS NAME "15.5–21.9% cropland" EXPRESSION (([cropland_pct] >= 15.5) AND ([cropland_pct] < 21.9)) STYLE COLOR 254 227 145 OUTLINECOLOR 205 170 75 WIDTH 0.4 END END
  CLASS NAME "21.9–27.5% cropland" EXPRESSION (([cropland_pct] >= 21.9) AND ([cropland_pct] < 27.5)) STYLE COLOR 254 196 79 OUTLINECOLOR 190 140 50 WIDTH 0.4 END END
  CLASS NAME "27.5–32.8% cropland" EXPRESSION (([cropland_pct] >= 27.5) AND ([cropland_pct] < 32.8)) STYLE COLOR 254 153 41 OUTLINECOLOR 180 105 45 WIDTH 0.4 END END
  CLASS NAME "32.8–38.6% cropland" EXPRESSION (([cropland_pct] >= 32.8) AND ([cropland_pct] < 38.6)) STYLE COLOR 236 112 20 OUTLINECOLOR 165 80 35 WIDTH 0.4 END END
  CLASS NAME "38.6–45.1% cropland" EXPRESSION (([cropland_pct] >= 38.6) AND ([cropland_pct] < 45.1)) STYLE COLOR 204 76 2 OUTLINECOLOR 135 60 20 WIDTH 0.4 END END
  CLASS NAME "45.1–52.8% cropland" EXPRESSION (([cropland_pct] >= 45.1) AND ([cropland_pct] < 52.8)) STYLE COLOR 153 52 4 OUTLINECOLOR 110 45 20 WIDTH 0.4 END END
  CLASS NAME "52.8–63.5% cropland" EXPRESSION (([cropland_pct] >= 52.8) AND ([cropland_pct] < 63.5)) STYLE COLOR 102 37 6 OUTLINECOLOR 80 35 20 WIDTH 0.4 END END
  CLASS NAME "63.5% cropland or more" EXPRESSION ([cropland_pct] >= 63.5) STYLE COLOR 69 25 8 OUTLINECOLOR 55 25 18 WIDTH 0.4 END END
END

