      TYPE TRUETYPE
      SIZE 9
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "50,000 - 80,000"
    EXPRESSION ([POPTOT] > 50000 AND [POPTOT] <= 80000)
    STYLE
      SYMBOL "star"
      SIZE 8
      COLOR 220 30 30
      OUTLINECOLOR 100 20 20
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 9
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "80,000 - 120,000"
    EXPRESSION ([POPTOT] > 80000 AND [POPTOT] <= 120000)
    STYLE
      SYMBOL "star"
      SIZE 10
      COLOR 230 20 20
      OUTLINECOLOR 80 10 10
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 10
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "120,000 - 200,000"
    EXPRESSION ([POPTOT] > 120000 AND [POPTOT] <= 200000)
    STYLE
      SYMBOL "star"
      SIZE 12
      COLOR 240 15 15
      OUTLINECOLOR 80 10 10
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 10
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "> 200,000"
    EXPRESSION ([POPTOT] > 200000)
    STYLE
      SYMBOL "star"
      SIZE 14
      COLOR 255 0 0
      OUTLINECOLOR 80 10 10
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial-bold"
      TYPE TRUETYPE
      SIZE 11
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
