    STYLE
      SYMBOL "circle"
      SIZE 9
      COLOR 255 144 141
      OUTLINECOLOR 100 50 50
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 10
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "> 150,000"
